UPDATE questions SET
  explanation = $EXPL$Correct (A): Under Treas. Reg. Section 1.1502-13, the $300,000 intercompany management fee is eliminated in the consolidated return, and under Treas. Reg. Section 1.1502-22, Ridge''s $400,000 capital losses offset Summit''s $400,000 capital gains on a consolidated basis. Consolidated taxable income is $2,000,000 with tax of $420,000, compared to $504,000 filing separately, saving approximately $84,000.
